                 where conname = 'family_members_customer_id_fkey' and conrelid = 'public.family_members'::regclass) then
    alter table public.family_members add constraint family_members_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
  end if;
